import java.util.*;class Solution{interface Fetch{String get(String key)throws Exception;}static String load(String key,Map<String,String>cache,Fetch fetch)throws Exception{String existing=cache.get(key);if(existing!=null)return existing;for(int attempt=1;;attempt++){try{String value=fetch.get(key);cache.put(key,value);return value;}catch(Transient error){if(attempt>=3)throw error;}}}static class Transient extends Exception{Transient(String message){super(message);}}}
